from lib import *
S = SS('l30')
steps = [
    step("git branch -m old-name new-name 改名:对象数 5 → 5,分支指向的提交没变(True);变的是 .git/refs/heads/ 和 .git/logs/refs/heads/ 下的文件名(old-name → new-name)、HEAD(ref: refs/heads/new-name)和 config(branch.old-name.* 变成 branch.new-name.*)。reflog 被一起带走,并多了一条 Branch: renamed refs/heads/old-name to refs/heads/new-name,原有的 commit 记录还在。但 branch.new-name.merge 的值仍是 refs/heads/old-name,git branch -vv 显示 [origin/old-name]——改名只动本地,远程的分支名没有变。", t=tl(S(1)), mark=lidx(S(1), 'Branch: renamed', 'branch.new-name.merge refs/heads/old-name', '[origin/old-name]', '对象数 5 → 5'), done=lidx(S(1), 'branch.old-name.remote', 'ref: refs/heads/new-name'), kv=KV([['对象', '一个都没变'], ['改变的', 'ref 文件、reflog 文件、config、HEAD'], ['远程', '不动,upstream 仍指向 origin/old-name']], ['远程'])),
    step("-m 不能覆盖已有的分支:git branch -m w victim 报 fatal: a branch named 'victim' already exists,退出码 128;-M 可以强制覆盖,victim 现在指向“只在w上”的提交。被覆盖的 victim 原来的那个提交(“victim独有的提交”)仍在对象库里(True),但没有任何分支包含它了——它成了不可达对象,等 gc 才会真的删除。", t=tl(S(2)), mark=lidx(S(2), 'already exists', '只在w上', '有分支包含它吗: False'), done=lidx(S(2), 'git branch -M'), kv=KV([['-m', '目标已存在则拒绝'], ['-M', '强制覆盖'], ['被覆盖的提交', '成为不可达对象,不会立刻删除']], ['-M'])),
    step("删除分支:git branch -d gone-soon 对未合并的分支报 error: the branch 'gone-soon' is not fully merged;-D 强制删除。删除时 .git/logs/refs/heads/ 里 gone-soon 的文件随之消失,但对象数 13 → 13,没有少,提交还在(True)。执行 git reflog expire --expire=now --all 与 git gc --prune=now 之后对象数降到 8,这个提交消失(False)——这一次清理还一并删掉了上一节被覆盖的 victim 的旧提交等其它不可达对象。", t=tl(S(3)), mark=lidx(S(3), 'not fully merged', '对象数 13 → 13', '对象数 8'), done=lidx(S(3), 'Deleted branch gone-soon', 'gone-soon main new-name victim', 'main new-name victim'), b=bars([['删分支前', 13, '13 个对象'], ['删分支后', 13, '13 个'], ['reflog expire + gc --prune=now 后', 8, '8 个']], 13, mark=[2], done=[0, 1]), kv=KV([['-d', '只删已合并的'], ['-D', '强制,但对象还在'], ['分支的 reflog', '随分支一起删除'], ['真正删除对象', '清 reflog 之后 gc --prune=now']], ['-D'])),
    step("-d 判断“已合并”的参照:有 upstream 的分支看 upstream,没有才看 HEAD。情形 A:feat1 已推送,合并进了自己的 upstream origin/feat1、但没合并进 HEAD:git branch -d 只给警告 deleting branch 'feat1' that has been merged to 'refs/remotes/origin/feat1', but not yet merged to HEAD,然后删除(Deleted branch feat1,列表里 0 个)。情形 B:feat2 合并进了 HEAD,但它的 upstream 是 origin/main(没有 feat2 的提交):git branch -d 拒绝:not deleting branch 'feat2' that is not yet merged to 'refs/remotes/origin/main', even though it is merged to HEAD;分支还在(1 个),要 -D。", t=tl(S(4)), mark=lidx(S(4), 'not deleting branch', 'deleting branch', 'Deleted branch feat2'), done=lidx(S(4), '情形 A', '情形 B', 'Deleted branch feat1'), kv=KV([['有 upstream', '看是否合并进 upstream'], ['没有 upstream', '看是否合并进 HEAD'], ['不一致时', '警告或拒绝']], ['有 upstream'])),
    step("删除当前所在的分支被拒绝:git branch -D main 报 error: cannot delete branch 'main' used by worktree at '…'——因为 main 正被这个工作树检出(多个工作树时,被任何一个工作树检出的分支都不能删)。先切换到别的分支再删。", t=tl(S(5)), mark=lidx(S(5), 'cannot delete branch'), done=lidx(S(5), 'git branch -D main'), kv=KV([['检出中的分支', '不能删'], ['含其它 worktree', '同样不能删'], ['办法', '先切换再删']], ['检出中的分支'])),
]
A = mkarti('l30', 30, 'Git,分支,改名,删除,git branch,对象,真实验证,动画演示',
    '在真实仓库里验证分支改名与删除对对象的影响:git branch -m 只动 ref 文件、reflog、config 与 HEAD(对象数 5 → 5,upstream 仍指向 origin/old-name);-M 覆盖已有分支会让原提交变成不可达对象;-D 删除分支后对象数不变(13 → 13),要清 reflog 并 gc --prune=now 才会真删(降到 8);-d 的“已合并”判据是 upstream 优先;检出中的分支无法删除。',
    '给分支改名、删除分支,.git 里到底改了什么?对象会不会跟着消失?这篇逐项验证:改名带走了什么、-M 覆盖掉的提交去了哪里、删分支后对象数怎么变、git branch -d 凭什么说“没合并”。',
    [('5 → 5', 'git branch -m 改名前后的对象总数,对象一个都没变'), ('13 → 13 → 8', '删除分支前后对象数不变,清 reflog 并 gc --prune=now 才降到 8'), ('upstream 优先', 'git branch -d 判断“已合并”时,有 upstream 就看 upstream,没有才看 HEAD')],
    [('改名只动本地的名字', '<p><code>git branch -m</code> 重命名 <code>.git/refs/heads/</code> 下的 ref 文件和 <code>logs</code> 下的 reflog 文件,更新 HEAD 与 config 里的 <code>branch.&lt;名&gt;.*</code>。reflog 被带走并多一条 <code>Branch: renamed</code>;对象一个都没变。远程上的分支名没改,upstream 仍指向旧名。</p>'),
     ('-M 覆盖', '<p>目标分支已存在时 <code>-m</code> 拒绝,<code>-M</code> 强制覆盖。被覆盖的分支原来的提交没有被删,但不再有分支包含它,成为不可达对象。</p>'),
     ('删除不删对象', '<p>删除分支只删 ref 和它的 reflog。提交、tree、blob 都还在对象库里,对象总数不变,直到 reflog 清空、<code>gc --prune</code> 之后才真正消失。想找回误删的分支见前面的 fsck 一篇。</p>'),
     ('-d 与已合并', '<p><code>-d</code> 只删“已合并”的分支。参照物:有 upstream 的看 upstream,没有看 HEAD。与 upstream 和 HEAD 的关系不一致时,会给警告(仍删除)或拒绝,并明确说出是针对哪个 ref。</p>'),
     ('当前分支', '<p>被任何工作树检出的分支不能删除,先切走。</p>')],
    steps,
    [ENV_I_GIT + '。远程是本机的一个裸仓库;对象总数 = git count-objects -v 里的 count + in-pack;输出里的 hash 做了替换;第三节的 13 → 8 包含此前被覆盖分支留下的不可达对象',
     '没有验证:git branch -c(复制分支);branch --move 对 worktree 中分支的处理;git branch --delete --remotes;remote 端分支改名(git push origin :old new 的完整流程,只在 refspec 一篇涉及推送);branch.<名>.description 等其它 config 项随改名的处理'],
    '分支改名与删除')
